\subsection{Generalized Pauli observables}
\label{sec:generalized-pauli}


For prime number $p$, the generalized Pauli operators over $\Fp$ are a
collection of observables indexed by a basis setting $X$ or $Z$ and an element
$a$ or $b$ of $\Fp$, with eigenvalues that are $p$-th roots of unity.
They are given by
\begin{equation}
  \label{eq:pauli-fp}
  \sigma^X(a) = \sum_{j \in \Fp} \ket{j + a} \bra{j}\qquad \text{and} \qquad
  \sigma^Z(b) = \sum_{j \in \Fp} \omega^{bj} \ket{j} \bra{j}\;,
\end{equation}
where $\omega = e^{\frac{2\pi i}{p}}$, and addition and multiplication are over
$\Fp$.
These observables obey the ``twisted commutation'' relations
\begin{equation}
  \label{eq:twisted-fp}
  \forall a,b\in\Fp\;,\qquad \sigma^X(a)\, \sigma^Z(b) =
  \omega^{-ab} \,\sigma^Z(b)\,\sigma^X(a)\;.
\end{equation}
Similarly, over a field $\Fq$ with $q$ a power of $p$, we can consider a set of generalized Pauli
operators, indexed by a basis setting $X$ or $Z$ and an element of $\Fq$ and
with eigenvalues that are $p$-th roots of unity.
For $a, b\in\Fq$ they are given by
\begin{equation*}
  \qp^X(a) = \sum_{j \in \Fq} \ket{j+a}\bra{j} \qquad \text{and} \qquad
  \qp^Z(b)= \sum_{j \in \Fq} \omega^{\tr(b j)} \ket{j}\bra{j}\;,
\end{equation*}
where addition and multiplication are over $\Fq$.
For all $W \in \{X,Z\}$, $a, a' \in \Fq$, and $b \in \Fp$, powers of these
observables obey the relations
\begin{equation*}\label{eq:pauli-product-power}
  \bigl(\qp^W(a)\qp^W(a')\bigr) = \qp^W(a+a') \qquad \text{and}
  \qquad \bigl( \qp^W(a) \bigr)^b = \qp^W(a b) \;.
\end{equation*}
In particular, since $pa=0$ for any $a\in \Fq$ we get that that $(\qp^W(a))^p =
I$ for any $a\in\Fq$.
The observables obey analogous ``twisted commutation'' relations
to~\eqref{eq:twisted-fp},
\begin{equation}
  \label{eq:twisted-fq}
  \forall a, b \in \Fq\;, \qquad \qp^X(a)\, \qp^Z(b) =
  \omega^{-\tr(a b)} \, \qp^Z(b)\, \qp^X(a)\;.
\end{equation}
It is clear from the definition that all of the $\qp^X$ operators commute with
each other, and similarly all the $\qp^Z$ operators commute with each other.
Thus, it is meaningful to speak of a common eigenbasis for all $\qp^X$
operators, and a common eigenbasis for all $\qp^Z$ operators.
The common eigenbasis for the $\qp^Z$ operators is the computational
basis $\{\ket{j}\}_{j \in \F_q}$.
To map this basis to the common eigenbasis of the $\qp^X$ operators, one can
apply the Fourier transform
\begin{equation}
  \label{eq:fourier-f}
  F \,=\, \frac{1}{\sqrt{q}} \sum_{a, b\in \Fq} \omega^{-\tr(ab)}
  \ket{a}\bra{b}\;.
\end{equation}
Explicitly, the eigenbases consist of the vectors $\ket{e_W}$ labeled by an
element $e \in \Fq$ and $W \in \{X, Z\}$, given by
\begin{equation*}
  \ket{e_X} = \frac{1}{\sqrt{q}} \sum_j \omega^{- \tr(e j)} \ket{j}\;, \qquad
  \ket{e_Z}   = \ket{e}\;.
\end{equation*}
We denote the POVM whose elements are projectors onto basis vectors of the
eigenbasis associated with the observables $\qp^W$ by $\{\qp^W_e\}_e$.
Then for all $W \in \{X,Z\}$ and $a\in \Fq$, the observables $\qp^W(a)$ can be
written as
\begin{equation}\label{eq:pauli-obs-proj-single}
  \qp^W(a) = \sum_{b \in \Fq} \omega^{\tr(a b)} \qp^W_b\;.
\end{equation}

To invert this relation, we first quote the following useful Fourier fact.
\begin{lemma}[Fact 3.2 of \cite{NW19}]
  \label{lem:cancellation}
  Let $V$ be a subspace of $\F^k$. For all $v \not\in V^\perp$, 
  \begin{equation*}
    \E_{u \sim V} \omega^{\tr(u \cdot v)} = 0\;,
  \end{equation*}
  where the expectation is over a uniformly random vector $u$ from $V$.
\end{lemma}

We may now invert~\Cref{eq:pauli-obs-proj-single}:
\begin{equation}\label{eq:pauli-inversion-0-single}
  \E_{a\in \F_q} \omega^{-\tr(ab)} \qp^W(a) = \sum_{b'\in \F_q} \E_{a\in \F_q}
  \omega^{\tr(a(b'-b))} \qp^W_{b'} = \qp^W_b\;,
\end{equation}
where the second step follows from Lemma~\ref{lem:cancellation}.

For systems with many qudits, we will consider tensor products of the operators
$\qp^W$.
Slightly abusing notation, for $W \in \{X, Z\}$ and $a \in \Fq^n$ we denote by
$\qp^W(a)$ the tensor product $\qp^W(a_1) \ot \dots \ot \qp^W(a_n)$.
These obey the twisted commutation relations
\begin{equation*}
  \forall a,b\in \Fq^n,\qquad \qp^X(a)\, \qp^Z(b) \,=\, \omega^{-\tr (a \cdot
    b)}\, \qp^Z(b)\, \qp^X(a)\;,
\end{equation*}
where $a \cdot b = \sum_{i=1}^{n} a_i b_i \in \Fq$.
For $W\in\{X,Z\}$ and $e \in \Fq^n$ define the eigenstates
\[ \ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}\;, \]
and associated rank-$1$ projectors $\qp^W_e$. Analogous versions of \Cref{eq:pauli-obs-proj-single}
and \Cref{eq:pauli-inversion-0-single} relate the multi-qubit observables
and projectors:
\begin{align}
  \qp^W(a) &= \sum_{b \in \Fq^n} \omega^{\tr(a \cdot b)}
  \qp^W_b\;, \label{eq:pauli-obs-proj} \\
    \E_{a\in \F_q^n} \omega^{-\tr(a \cdot b)} \qp^W(a) &= \sum_{b'\in \F_q^n} \E_{a\in \F_q^n}
  \omega^{\tr(a\cdot (b'-b))} \qp^W_{b'} = \qp^W_b\;. \label{eq:pauli-inversion-0}
\end{align}

Since we only consider finite fields $\F_q$ such that $q = 2^k$ the maximally
entangled state $\ket{\EPR_q}$ and the corresponding qudit Pauli
observables/projectors are isomorphic to a tensor product of maximally entangled
states $\ket{\EPR_2}$ and \emph{qubit} Pauli observables/projectors
respectively; this is shown in the next lemma.
This is used to argue that the Pauli basis test (described in
Section~\ref{sec:pauli-verifier}) gives a self-test for Pauli observables and
maximally entangled states over qubits.

\begin{lemma}
  \label{lem:pauli-binary}
  For all admissible field sizes $q = 2^k$ and integers $L$, there exists
  an isomorphism $\phi: (\C^q)^{\otimes L} \to (\C^2)^{\otimes L k}$
  such that\footnote{ Here we have applied the natural identifications between
  $(\C^q)^{\ot L} \ot (\C^q)^{\ot L}$ and $(\C^q \ot \C^q)^{\ot L}$,
  and between $(\C^2)^{\ot L k} \ot (C^2)^{\ot Lk}$ and $(\C^2 \ot
  \C^2)^{\ot Lk}$.}
\begin{equation}

	$L^{\mathrm{Ln}}_v : \F_q^m \to \F_q^m$ denote the canonical linear map with
	the one-dimensional kernel basis $\{v\}$
	(Definition~\ref{def:cl-canonical}). The \emph{canonical representative of
	$\ell$} is the point $u_0 \in \F_q^m$ such that
	\[
		u_0 = L^{\mathrm{Ln}}_v(u) \qquad \text{for all } u \in \ell\;.
	\]
	This is well defined: since the image and kernel of $L^{\mathrm{Ln}}_v$ are
	complementary, any $u \in \ell$ decomposes uniquely as $u = u_0 + tv$ with
	$u_0$ in the image, so $u_0 = u - tv \in \ell$ and
	$L^{\mathrm{Ln}}_v(u_0) = u_0$; moreover any two points of $\ell$ differ by
	a multiple of $v$ and therefore have the same image under
	$L^{\mathrm{Ln}}_v$. A line $\ell = \ell(u,v)$ is henceforth canonically
	represented by the pair $(u_0, v)$. (For $v = 0$, where the singleton
	$\{u\}$ leaves no independent kernel basis, we take $L^{\mathrm{Ln}}_0$ to
	be the identity---the canonical linear map with empty kernel basis---so
	that $u_0 = u$; the source leaves this case implicit.)
\end{definition}

\section{Quantum registers and EPR states}
% Paper label sec:lin-reg kept for cross-reference fidelity.
\label{sec:lin-reg}

\begin{definition}[State space of a linear register]\label{def:lin-reg}
	\uses{def:complementary}
	For a set $V$, we write $\C^V$ for the complex vector space of dimension
	$|V|$, endowed with the canonical orthonormal basis
	$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
	$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
	subspaces over $\F$, then $\C^V$ is identified with
	$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
	$\ket{x_1 \oplus \dots \oplus x_k}$ with
	$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
	$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
	$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
	the \emph{qudits} of $\C^V$.
\end{definition}

\begin{definition}[EPR state]\label{def:EPR}
	\uses{def:lin-reg}
	For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
	$\C^V \ot \C^V$ is
	\[
		\ket{\mathrm{EPR}}_V
		= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
	\]
	We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
	$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
\end{definition}

\section{Generalized Pauli observables}
% Paper label sec:generalized-pauli kept for cross-reference fidelity.
\label{sec:generalized-pauli}

\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
	\lean{MIPStarRE.QPBT.primeTauShift, MIPStarRE.QPBT.primeTauPhase}
	\lean{MIPStarRE.QPBT.primeTauObservable}
	\uses{def:subfield-trace, def:lin-reg}
	Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
	observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
	\begin{equation}\label{eq:pauli-fp}
		\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
	\end{equation}
	for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
	\emph{generalized Pauli observables over $\F_q$} are the unitaries on
	$\C^{\F_q}$
	\[
		\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
	\]
	for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
	(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
	the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
	signs. All the $\tau^X$ operators commute with one another, as do all the
	$\tau^Z$ operators. Their common eigenbases consist of the vectors
	$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
	\[
		\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
		\omega^{-\tr(ej)} \ket{j}\;, \qquad
		\ket{e_Z} = \ket{e}\;;
	\]
	the Fourier transform
	\begin{equation}\label{eq:fourier-f}
		F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
		\omega^{-\tr(ab)} \ket{a}\bra{b}
	\end{equation}
	maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
	$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
	are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
	systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
	\[
		\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
		\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
	\]
	for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
\end{definition}

\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
	\lean{MIPStarRE.QPBT.primeTauObservable_mul}
	\lean{MIPStarRE.QPBT.primeTauObservable_pow}
	\lean{MIPStarRE.QPBT.primeTauObservable_pow_char}
	\lean{MIPStarRE.QPBT.primeTauObservable_isUnitary}
	\lean{MIPStarRE.QPBT.primeTauObservable_eigenvalue_pow_char}
	\lean{MIPStarRE.QPBT.primeTauObservable_X_mul_Z}
	\leanok
	\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
	Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
	\begin{enumerate}
		\item For all $a, a' \in \F_q$ and $b \in \F_p$,
		      \begin{equation}\label{eq:pauli-product-power}
			      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
			      \qquad \text{and} \qquad
			      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
		      \end{equation}
		      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$. By the explicit
		      definitions each $\tau^W(a)$ is unitary, and its eigenvalues are
		      $p$-th roots of unity.
		\item For all $a, b \in \F_q^n$,
		      % Paper equation label kept on the display it names.
		      \begin{equation}\label{eq:twisted-fq}
			      \tau^X(a)\, \tau^Z(b)
			      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
		      \end{equation}
		      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
		      $q = p$, $n = 1$ reads
		      \begin{equation}\label{eq:twisted-fp}
			      \sigma^X(a)\, \sigma^Z(b)
			      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
			      \qquad \text{for all } a, b \in \F_p\;.
		      \end{equation}
	\end{enumerate}
\end{lemma}
\begin{proof}
	\uses{def:generalized-pauli, def:subfield-trace}
	All identities are verified on computational basis states. For the product
	relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
	$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
	combine by $\F_q$-linearity of the trace, and the power relation follows by
	iterating. For the scalar twisted commutation,
	$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
	$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
	\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
	follows by applying the scalar relation factor by factor and summing the
	exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
	trace is the identity map, which gives \eqref{eq:twisted-fp}.
\end{proof}

\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
	\lean{MIPStarRE.QPBT.ffChar_dotProduct_submodule_expect_eq_zero}
	\leanok
	\uses{def:dot-product-orthogonal, def:subfield-trace}
	Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
	$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
	$v \notin V^\perp$,
	\[
		\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
	\]
	where the expectation is over a uniformly random vector $\bu$ in $V$.
\end{lemma}
\begin{proof}
	This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
	the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
	on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
	shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
	for the expectation, translation invariance of the uniform distribution on
	$V$ gives
	$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
	= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
	forces $C = 0$.
\end{proof}

